<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Обязательна ли экспертиза результатов по каждому контракту?", "acceptedAnswer": {"@type": "Answer", "text": "Да. По части 3 статьи 94 закона № 44-ФЗ заказчик обязан провести экспертизу результатов по каждому контракту и каждому отдельному этапу. Выбор только в форме: своими силами или с привлечением внешних экспертов."}}, {"@type": "Question", "name": "Когда обязательно привлекать внешних экспертов?", "acceptedAnswer": {"@type": "Answer", "text": "Общего случая в законе нет: часть 4 статьи 94, требовавшая внешнюю экспертизу при закупках у единственного поставщика, утратила силу с 2019 года. Правительство вправе установить случаи обязательной внешней экспертизы отдельными актами (ч. 4.1 ст. 94)."}}, {"@type": "Question", "name": "Продлевает ли экспертиза срок приёмки?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Экспертиза проводится внутри срока приёмки: по контрактам с электронным актированием заказчик обязан подписать документ о приёмке или разместить мотивированный отказ не позднее 20 рабочих дней после поступления документа (ч. 13 ст. 94)."}}, {"@type": "Question", "name": "Как оформляется экспертиза своими силами?", "acceptedAnswer": {"@type": "Answer", "text": "Форма законом не установлена. Достаточно подписания документа о приёмке уполномоченным лицом; внутреннее заключение, приказ или отметка «экспертиза проведена» — право заказчика, а не обязанность."}}, {"@type": "Question", "name": "Может ли эксперт запрашивать документы у исполнителя?", "acceptedAnswer": {"@type": "Answer", "text": "Да. По части 5 статьи 94 эксперты вправе запрашивать у заказчика и поставщика дополнительные материалы об условиях исполнения контракта. Отвечать письменно и в срок — в интересах исполнителя."}}, {"@type": "Question", "name": "Что значит заключение с предложениями об устранении?", "acceptedAnswer": {"@type": "Answer", "text": "Если нарушения не препятствуют приёмке, заключение может содержать предложения об их устранении с указанием срока. Это промежуточный исход: устраните замечания и направьте документ о приёмке повторно."}}, {"@type": "Question", "name": "Обязан ли заказчик следовать заключению экспертов?", "acceptedAnswer": {"@type": "Answer", "text": "Заказчик обязан учитывать предложения из заключения при решении о приёмке или отказе (ч. 7 ст. 94), но решение принимает сам. Отрицательное заключение не заменяет мотивированный отказ, положительное не гарантирует подпись."}}, {"@type": "Question", "name": "Кто не может быть экспертом?", "acceptedAnswer": {"@type": "Answer", "text": "Лица, зависимые от заказчика или исполнителя: их работники, в том числе уволившиеся менее двух лет назад, близкие родственники должностных лиц, лица с имущественным интересом в контракте (ст. 41 закона № 44-ФЗ)."}}, {"@type": "Question", "name": "Какая ответственность у эксперта за ложное заключение?", "acceptedAnswer": {"@type": "Answer", "text": "За заведомо ложное экспертное заключение в сфере закупок, повлёкшее крупный ущерб или вред здоровью, установлена уголовная ответственность по статье 200.6 УК РФ."}}, {"@type": "Question", "name": "Чем приёмочная экспертиза отличается от экспертизы при расторжении?", "acceptedAnswer": {"@type": "Answer", "text": "Приёмочная (ст. 94) проверяет результат перед подписью документа о приёмке. Экспертиза при одностороннем отказе (ч. 10–11 ст. 95) подтверждает нарушения как основание расторжения контракта — на кону весь контракт и реестр недобросовестных поставщиков."}}, {"@type": "Question", "name": "Как экспертиза влияет на оплату при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Платёж заказчика санкционируется по документам-основаниям, главный из которых — подписанный документ о приёмке. Пока экспертиза не завершена и документ не подписан, оплата этапа не пройдёт; после подписи — 10 рабочих дней на оплату."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как исполнителю пройти экспертизу результатов исполнения контракта", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Узнайте формат экспертизы заранее", "text": "Ещё на этапе исполнения письменно уточните у заказчика: экспертиза своими силами или внешняя, кто эксперт, какие материалы понадобятся."}, {"@type": "HowToStep", "position": 2, "name": "Готовьте результат под проверку", "text": "Комплектность, паспорта, сертификаты, исполнительная документация и протоколы испытаний — каждый пункт технического задания закрывается документом."}, {"@type": "HowToStep", "position": 3, "name": "Отвечайте на запросы экспертов", "text": "Эксперты вправе запрашивать материалы у исполнителя (ч. 5 ст. 94). Отвечайте письменно и в срок — ответы лягут в основу заключения."}, {"@type": "HowToStep", "position": 4, "name": "Следите за сроками приёмки", "text": "Экспертиза не продлевает срок: подпись или мотивированный отказ — не позднее 20 рабочих дней после поступления документа о приёмке (ч. 13 ст. 94)."}, {"@type": "HowToStep", "position": 5, "name": "Работайте с заключением", "text": "Замечания с предложениями об устранении закрывайте в срок и направляйте документ о приёмке повторно; при несогласии готовьте возражения по пунктам."}, {"@type": "HowToStep", "position": 6, "name": "При отказе действуйте по процедуре", "text": "Проверяйте мотивированный отказ на соответствие заключению; недобросовестные решения обжалуйте в УФАС и суде."}]}
</script>
